(function(){
'use strict';
const completed=f=>['parsed','fileFinal','contentFinal'].includes(f.status),allowed=f=>['pending','failed'].includes(f.status)&&!f.archive&&!f.unsupported;
function state(){return S.materialFolders||(S.materialFolders={selected:[],closed:{},packages:[],folders:[],message:'原件与解析稿仅保存在页面内存，刷新会丢失；请及时下载。',importing:false,epoch:0,hidden:[]});}
function visible(){return S.files.filter(f=>!f.ownerProjectId||f.ownerProjectId===S.proj?.id);}
function source(f){return f.sourcePath||f.name;}
function output(f){if(f.mdPath)return f.mdPath;const used=new Set(S.files.filter(x=>x!==f).map(x=>x.mdPath?.toLowerCase()).filter(Boolean));let p=source(f).replace(/\.[^/.]+$/,'')+'.md';if(used.has(p.toLowerCase()))p=source(f)+'.md';let n=2,base=p;while(used.has(p.toLowerCase()))p=base.replace(/\.md$/,'-'+n+++'.md');return f.mdPath=p;}
function say(s){state().message=s;render();}
window.v11ToggleFolder=function(key){state().closed[key]=!state().closed[key];render();};
window.v11SelectFolder=function(prefix,on){const s=state(),ids=visible().filter(f=>allowed(f)&&source(f).startsWith(prefix)).map(f=>f.id);s.selected=s.selected.filter(id=>!ids.includes(id));if(on)s.selected.push(...ids);render();};
window.v11SelectFile=function(id,on){const s=state();s.selected=s.selected.filter(x=>x!==id);if(on&&allowed(S.files.find(f=>f.id===id)||{}))s.selected.push(id);render();};
function folderToggle(key){return 'v11ToggleFolder('+esc(JSON.stringify(key))+')';}
function row(f,kind){const name=(kind==='parsed'?output(f):source(f)).split('/').at(-1),label=ST_LABEL[f.status]||['不可解析','gray'];return '<div class="file-row '+(kind==='parsed'&&S.selFile===f.id?'sel':'')+'" data-material-file="'+f.id+'">'+(kind==='original'?'<input class="pk" type="checkbox" value="'+f.id+'" '+(state().selected.includes(f.id)?'checked ':'')+(!allowed(f)?'disabled ':'')+' onchange="v11SelectFile(\''+f.id+'\',this.checked)">':'')+'<button class="ghost v11-file-name" title="'+esc(source(f))+'" onclick="v11Open(\''+f.id+'\',\''+kind+'\')">'+(kind==='parsed'?'📄':f.icon||'📎')+' '+esc(name)+'</button><span class="tag '+label[1]+'">'+(f.archive?(f.extractedPath?'已解压':'待解压'):f.unsupported?'不支持解析':label[0])+'</span>'+(kind==='parsed'?'<input type="checkbox" aria-label="选择定稿 '+esc(name)+'" data-final-select="'+f.id+'" '+((state().finalSelected||[]).includes(f.id)?'checked ':'')+(f.status!=='parsed'?'disabled ':'')+' onchange="v11SelectFinal(\''+f.id+'\',this.checked)"><button class="ghost sm" title="删除解析稿" onclick="v11DeleteParsed(\''+f.id+'\')">🗑</button>':(f.archive&&f.originalBlob?'<button class="sm" onclick="v11Extract(\''+f.id+'\')">'+(f.extractedPath?'查看文件夹':'解压')+'</button>':'')+'<button class="ghost sm" title="删除原件及关联解析稿" onclick="delFile(\''+f.id+'\')">🗑</button>')+'</div>'+(f.status==='parsing'?'<div class="prog"><i style="width:'+(f.prog||0)+'%"></i></div>':'')+(f.failMsg?'<div class="dz-note" style="padding:4px 12px;color:var(--red)">'+esc(f.failMsg)+(f.status==='failed'&&allowed(f)?' <button class="sm" onclick="retryParse(\''+f.id+'\')">重试</button>':'')+'</div>':'');}
function tree(files,kind){const root={dirs:new Map(),files:[]};function addDir(parts){let node=root;for(const name of parts){if(!node.dirs.has(name))node.dirs.set(name,{dirs:new Map(),files:[]});node=node.dirs.get(name);}return node;}for(const f of files){const parts=(kind==='parsed'?output(f):source(f)).split('/');parts.pop();addDir(parts).files.push(f);}if(kind==='original'&&state().pendingOnly===false)for(const d of state().folders.filter(x=>x.project===S.proj?.id))addDir(d.path.split('/'));
function html(node,prefix){return [...node.dirs].map(([name,child])=>{const p=prefix+name+'/',key=kind+':'+p.slice(0,-1),ids=files.filter(f=>allowed(f)&&source(f).startsWith(p)).map(f=>f.id),count=ids.filter(id=>state().selected.includes(id)).length;return '<div class="v11-folder"><div class="v11-folder-head">'+(kind==='original'?'<input type="checkbox" '+(!ids.length?'disabled ':'')+(count&&count===ids.length?'checked ':'')+'data-partial="'+(count>0&&count<ids.length)+'" aria-label="勾选 '+esc(p)+'" onchange="v11SelectFolder('+esc(JSON.stringify(p))+',this.checked)">':'')+'<button class="ghost" aria-expanded="'+!state().closed[key]+'" onclick="'+folderToggle(key)+'">'+(state().closed[key]?'▸':'▾')+' 📁 '+esc(name)+'</button></div><div '+(state().closed[key]?'hidden':'')+'>'+html(child,p)+'</div></div>';}).join('')+node.files.map(f=>row(f,kind)).join('');}return html(root,'')||'<div class="empty-tip">暂无文件</div>';}
for(const f of S.files)if(/\.zip$/i.test(f.name)){f.archive=true;f.unsupported=true;f.failMsg='V1.9 压缩包样例没有真实二进制，请上传实际 ZIP 自动解压。';}
window.v11DownloadPackage=function(index){const pack=state().packages[index];if(pack&&pack.project===S.proj?.id)download(pack.blob,pack.name);};
const previousFile=window.matFileHtml;
window.matFileHtml=function(){const t=document.createElement('template');t.innerHTML=previousFile();const left=t.content.querySelector('.panel-left'),s=state(),files=visible();s.selected=s.selected.filter(id=>files.some(f=>f.id===id&&allowed(f)));left.classList.add('v11-material-left');left.innerHTML='<div class="upload-zone"><label style="cursor:pointer">⬆ 上传文件 / ZIP<input id="material-upload" type="file" multiple style="display:block;max-width:100%;margin-top:8px" onchange="v11Import(this.files)"></label><div class="dz-note">ZIP 上传后点击行内“解压” · Markdown 原文读取<br>其他格式沿用 V1.9 模拟解析</div><button class="ghost sm" onclick="mockUpload()">使用 V1.9 示例上传</button></div><div class="pl-head"><input type="checkbox" aria-label="全选待解析" onchange="v11SelectFolder(\'\',this.checked)"> 📁 原始文件 · 待解析'+files.filter(allowed).length+' <label class="dz-note"><input id="material-pending-only" type="checkbox" '+(s.pendingOnly!==false?'checked':'')+' onchange="S.materialFolders.pendingOnly=this.checked;render()">仅待解析</label></div><div class="filelist" data-material-root="original">'+tree(files.filter(f=>s.pendingOnly===false||['pending','parsing','failed'].includes(f.status)),'original')+(s.pendingOnly===false?s.packages:[]).map((p,i)=>p.project===S.proj?.id?'<div style="padding:4px 12px"><button class="ghost sm" onclick="v11DownloadPackage('+i+')">📦 下载 '+esc(p.name)+' 原包</button></div>':'').join('')+'</div><div style="padding:10px 12px"><button class="primary" '+(S.parsing||s.importing?'disabled':'')+' onclick="batchParse()">'+(S.parsing?'解析中…':'批量解析（已选 '+s.selected.length+'）')+'</button></div><div class="pl-head">📁 解析文件 · Markdown <button class="sm" onclick="v11BatchFinal()">批量定稿（'+(s.finalSelected||[]).length+'）</button></div><div class="filelist" data-material-root="parsed">'+tree(files.filter(completed),'parsed')+'</div><div class="dz-note" role="status" style="padding:12px">'+esc(s.message)+'</div>';const current=files.filter(completed).find(f=>f.id===S.selFile)||files.find(completed);if(current){const title=document.createElement('div');title.className='pl-head';title.dataset.materialTitle='parsed';title.textContent='解析文件 / '+output(current);t.content.querySelector('.doc-area')?.prepend(title);}return t.innerHTML;};
const previousRender=window.render;window.render=function(){const result=previousRender.apply(this,arguments);document.querySelectorAll('[data-partial="true"]').forEach(x=>x.indeterminate=true);return result;};
window.v11Open=function(id,kind){const f=visible().find(x=>x.id===id);if(!f)return;if(kind==='parsed'){if(!completed(f))return;closeModal();S.selFile=id;S.quote=null;render();return;}modal('<div class="m-head">原始文件<button class="ghost" onclick="closeModal()">✕</button></div><div class="m-body"><p>'+esc(source(f))+'</p><p>'+esc(f.originalBlob?'原始二进制保留，不因解析而覆盖。':'V1.9 演示样例，没有真实原始二进制。')+'</p><p>状态：'+esc((ST_LABEL[f.status]||['未知'])[0])+'</p></div><div class="m-foot">'+(f.originalBlob?'<button onclick="v11Download(\''+f.id+'\',true)">下载原件</button>':'')+(completed(f)?'<button onclick="closeModal();v11Open(\''+f.id+'\',\'parsed\')">查看解析稿</button>':'')+'<button onclick="closeModal()">关闭</button></div>');};
function unique(p,paths){const has=x=>paths.some(y=>y.toLowerCase()===x.toLowerCase()||y.toLowerCase().startsWith(x.toLowerCase()+'/'));let n=2,b=p;while(has(p))p=b+' ('+n+++')';return p;}
window.v11Import=async function(list){const s=state();if(s.importing||S.parsing){say('当前任务处理中，请稍后上传');return;}const files=Array.from(list),project=S.proj?.id,epoch=++s.epoch;s.importing=true;s.message='正在读取并校验上传文件…';render();const messages=[];try{for(const file of files){try{let entries,base='',isZip=/\.zip$/i.test(file.name);const paths=S.files.map(source).concat(s.packages.filter(x=>x.project===project).map(x=>x.path));if(isZip){if(file.size>30*1024*1024)throw Error('压缩包超过30MB');const path=unique(MaterialZip.path(file.name),paths);S.files.push({id:uid(),name:path,sourcePath:path,ownerProjectId:project,originalBlob:file,archive:true,icon:'📦',size:file.size+' B',up:now().slice(0,10),status:'pending',md:null,contentMd:null,attach:[],ops:[]});messages.push(file.name+'：原包已上传，请点击解压');continue;}else{if(file.size>10*1024*1024)throw Error('单文件超过10MB');entries=[{path:unique(MaterialZip.path(file.name),paths),bytes:new Uint8Array(await file.arrayBuffer()),directory:false}];}if(s.epoch!==epoch||S.proj?.id!==project)throw Error('项目已切换，本次上传未写入');const records=[],folders=[];for(const e of entries){const p=(base?base+'/':'')+e.path;if(e.directory){folders.push({project,path:p});continue;}const unsupported=/\.(zip|png|jpe?g|gif|webp|mp[34]|wav|avi|7z|rar)$/i.test(p);records.push({id:uid(),name:p,sourcePath:p,ownerProjectId:project,originalBlob:new Blob([e.bytes]),icon:'📎',size:e.bytes.length+' B',up:now().slice(0,10),status:'pending',md:null,contentMd:null,attach:[],ops:[],unsupported,failMsg:unsupported?'原件已保留；该类型不支持解析，嵌套压缩包不递归解压。':null});}S.files.push(...records);s.folders.push(...folders);if(isZip)s.packages.push({project,path:base,blob:file,name:file.name});messages.push(file.name+'：已导入 '+records.length+' 个文件');}catch(e){messages.push(file.name+'：'+e.message);}if(s.epoch!==epoch||S.proj?.id!==project)break;}}finally{if(s.epoch===epoch){s.importing=false;s.message=messages.join('；')+'。导入结果仅保存在页面内存，刷新即丢失；如需留存请逐份下载。';render();}}};
window.v11Extract=async function(id){const s=state(),f=visible().find(x=>x.id===id);if(!f?.archive||!f.originalBlob)return;if(f.extractedPath){s.pendingOnly=false;for(const key of Object.keys(s.closed))if(key.startsWith('original:'+f.extractedPath))s.closed[key]=false;render();return;}if(s.importing||S.parsing)return;const epoch=++s.epoch,project=S.proj?.id;s.importing=true;s.message='正在校验并解压 '+source(f);render();try{const entries=await MaterialZip.read(await f.originalBlob.arrayBuffer());if(s.epoch!==epoch||S.proj?.id!==project||!S.files.includes(f))return;const base=unique(source(f).replace(/\.zip$/i,''),S.files.map(source).concat(s.folders.filter(x=>x.project===project).map(x=>x.path)));const records=entries.filter(e=>!e.directory).map(e=>{const path=base+'/'+e.path,archive=/\.zip$/i.test(path),unsupported=/\.(png|jpe?g|gif|webp|mp[34]|wav|avi|7z|rar)$/i.test(path);return {id:uid(),name:path,sourcePath:path,ownerProjectId:project,originalBlob:new Blob([e.bytes]),archive,unsupported,icon:archive?'📦':'📎',size:e.bytes.length+' B',up:now().slice(0,10),status:'pending',md:null,contentMd:null,attach:[],ops:[]};});S.files.push(...records);s.folders.push({project,path:base},...entries.filter(e=>e.directory).map(e=>({project,path:base+'/'+e.path})));f.extractedPath=base;f.failMsg=null;s.closed['original:'+base]=false;s.message='解压完成：'+records.length+' 个文件，原压缩包保留';}catch(e){if(s.epoch===epoch&&S.files.includes(f)){f.failMsg='解压失败：'+e.message;s.message=f.failMsg;}}finally{if(s.epoch===epoch){s.importing=false;render();}}};
function deleteReason(f){if(!f||!completed(f))return '解析稿已不存在';if(f.status!=='parsed')return '请先解锁文件解析及内容定稿';if(f.contentMd!=null||(f.contentResults||[]).length||(f.attach||[]).length||(f.ops||[]).length)return '已有内容加工或附件依赖，不能删除解析稿';if([S.crd,S.prd].some(d=>(d.refs||[]).includes(f.id)||(d.versions||[]).some(v=>JSON.stringify(v.inputSnapshot||{}).includes(f.id))))return '已有需求引用依赖，不能删除解析稿';return '';}
function snapshot(f){return JSON.stringify([f.id,f.status,f.md,f.contentMd,f.contentResults,f.attach,f.ops]);}
window.v11DeleteParsed=function(id){const s=state(),f=visible().find(x=>x.id===id),reason=deleteReason(f);s.deleteParsed=null;if(reason){modal('<div class="m-head">不能删除解析稿</div><div class="m-body">'+esc(reason)+'</div><div class="m-foot"><button onclick="closeModal()">关闭</button></div>');return;}s.deleteParsed={id,project:S.proj.id,snapshot:snapshot(f)};modal('<div class="m-head">删除解析稿</div><div class="m-body">仅删除 '+esc(output(f))+'，保留原文件及原压缩包。原件将恢复待解析。</div><div class="m-foot"><button onclick="closeModal()">取消</button><button onclick="v11ConfirmDeleteParsed()">确认删除解析稿</button></div>');};
window.v11ConfirmDeleteParsed=function(){const s=state(),d=s.deleteParsed,f=d&&visible().find(x=>x.id===d.id);if(!d||d.project!==S.proj?.id||deleteReason(f)||snapshot(f)!==d.snapshot){s.deleteParsed=null;closeModal();say('文件或依赖已变化，未删除，请重新检查');return;}f.md=null;f.status='pending';f.failMsg=null;f.prog=0;s.finalSelected=(s.finalSelected||[]).filter(id=>id!==f.id);if(S.selFile===f.id)S.selFile=null;if(S.selContentFile===f.id)S.selContentFile=null;s.deleteParsed=null;closeModal();logEvent('stage.material',output(f)+' 解析稿已删除，原件保留');say('解析稿已删除；原件保留，可重新解析');};
window.v11SelectFinal=function(id,on){const s=state();s.finalSelected=(s.finalSelected||[]).filter(x=>x!==id);if(on&&visible().some(f=>f.id===id&&f.status==='parsed'))s.finalSelected.push(id);render();};
window.v11BatchFinal=function(){const s=state(),ids=s.finalSelected||[],files=ids.map(id=>visible().find(f=>f.id===id)),valid=f=>f&&f.status==='parsed'&&typeof f.md==='string';s.batchFinal=null;if(!ids.length){toast('请勾选需要定稿的解析稿','warn');return;}const blocked=files.filter(f=>!valid(f));if(blocked.length||S.parsing||s.importing){say('存在文件状态变化或运行任务，未进入批量定稿，请重新选择');return;}s.batchFinal={project:S.proj.id,ids:ids.slice(),snapshots:files.map(snapshot)};modal('<div class="m-head">批量文件解析定稿</div><div class="m-body"><p>请确认已复核以下 '+files.length+' 份解析稿；仅完成文件解析定稿，不完成内容或需求定稿。</p><ul>'+files.map(f=>'<li>'+esc(output(f))+'</li>').join('')+'</ul></div><div class="m-foot"><button onclick="closeModal()">取消</button><button onclick="v11ConfirmBatchFinal()">确认批量定稿</button></div>');};
window.v11ConfirmBatchFinal=function(){const s=state(),b=s.batchFinal;if(!b)return;const files=b.ids.map(id=>visible().find(f=>f.id===id));if(b.project!==S.proj?.id||S.parsing||s.importing||files.some((f,i)=>!f||f.status!=='parsed'||snapshot(f)!==b.snapshots[i])){s.batchFinal=null;closeModal();say('确认期间文件发生变化，本批未定稿，请重新复核');return;}for(const f of files){f.status='fileFinal';logEvent('stage.material',output(f)+' 人工批量文件解析定稿');}s.batchFinal=null;s.finalSelected=[];closeModal();say('已确认 '+files.length+' 份文件解析定稿；未改变内容及需求定稿');};
window.batchParse=function(){const s=state();if(S.parsing||s.importing)return;const files=visible().filter(f=>s.selected.includes(f.id)&&allowed(f));if(!files.length){toast('请先勾选要解析的文件','warn');return;}v11Parse(files);};
async function v11Parse(files){const s=state(),project=S.proj?.id,epoch=++s.epoch;S.parsing=true;s.selected=s.selected.filter(id=>!files.some(f=>f.id===id));pushChat('material','user','批量解析 '+files.length+' 个文件');for(const f of files){f.status='parsing';f.prog=5;f.parseEpoch=epoch;}render();for(const f of files){try{await new Promise(resolve=>setTimeout(resolve,300));if(epoch!==s.epoch||project!==S.proj?.id)break;if(!S.files.includes(f)||f.parseEpoch!==epoch)continue;let md;if(f.failPreset==='encrypted')throw Error('文件已加密，请解除密码后重新上传');if(f.failPreset==='needsOcr')throw Error('第 3、7 页为扫描页，需要外部 OCR 文字稿');if(f.originalBlob&&/\.md$/i.test(source(f)))md=new TextDecoder('utf-8',{fatal:true}).decode(await f.originalBlob.arrayBuffer());else if(!f.originalBlob&&f.id==='f1')md=MD_TENDER;else if(!f.originalBlob&&f.id==='f2')md=MD_INTERVIEW;else md='# '+source(f)+'\n\n> 离线原型模拟解析：未读取此文件真实正文，不能用于真实需求依据。\n\n## 待复核\n请使用实际转换工具提供 Markdown 后再复核。';if(epoch!==s.epoch||project!==S.proj?.id||!S.files.includes(f)||f.parseEpoch!==epoch)continue;f.md=md;f.status='parsed';f.prog=100;f.failMsg=null;output(f);S.selFile=f.id;logEvent('stage.material',source(f)+' 解析完成'+(f.originalBlob&&!/\.md$/i.test(source(f))?'（模拟）':''));}catch(e){if(epoch===s.epoch&&S.files.includes(f)){f.status='failed';f.failMsg=e.message;f.failType=f.failPreset||'read';}}}if(epoch===s.epoch){S.parsing=false;s.message='本轮解析结束：成功 '+files.filter(f=>f.status==='parsed').length+'，失败 '+files.filter(f=>f.status==='failed').length+'。原件保留；定稿仍需人工确认。';pushChat('material','ai',s.message);render();}}
const previousRetry=window.retryParse;window.retryParse=function(id){const f=visible().find(x=>x.id===id);if(!f||S.parsing)return;if(f.originalBlob){if(allowed(f))v11Parse([f]);return;}return previousRetry(id);};
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
window.v11Download=function(id,original){const f=visible().find(x=>x.id===id);if(!f)return;const blob=original?f.originalBlob:new Blob([f.md||''],{type:'text/markdown;charset=utf-8'});if(!blob){toast('演示样例未保存真实原件','warn');return;}download(blob,(original?source(f):output(f)).split('/').at(-1));};
window.dlFilePopover=function(btn){const f=visible().filter(completed).find(f=>f.id===S.selFile)||visible().find(completed);if(!f)return;popover(btn,'<div class="po-head">下载</div><div class="po-item" onclick="closePopover();v11Download(\''+f.id+'\',false)">解析稿 Markdown (.md)</div><div class="po-item" onclick="closePopover();v11Download(\''+f.id+'\',true)">原文件'+(f.originalBlob?'':'（样例无原件）')+'</div>');};
const previousReparse=window.reparse;window.reparse=function(){const f=visible().find(f=>f.id===S.selFile);if(f?.originalBlob){toast('真实上传文件请先保留当前编辑稿，本轮不支持覆盖式重新解析','warn');return;}return previousReparse();};
const previousProject=window.openProject;window.openProject=function(id){const s=state();s.epoch++;s.importing=false;S.parsing=false;for(const f of S.files)if(f.status==='parsing'&&f.parseEpoch){f.status='pending';f.prog=0;}const all=S.files.concat(s.hidden);s.hidden=all.filter(f=>f.ownerProjectId&&f.ownerProjectId!==id);S.files=all.filter(f=>!f.ownerProjectId||f.ownerProjectId===id);s.selected=[];return previousProject.apply(this,arguments);};
window.curContentFile=function(){const files=visible().filter(completed);return files.find(f=>f.id===S.selContentFile)||files[0];};
function selectedResult(f){return (f.contentResults||[]).find(a=>a.id===state().contentResult&&a.sourceId===f.id);}
window.v11OpenContent=function(id,result){const f=visible().find(f=>f.id===id&&completed(f));if(!f)return;S.selContentFile=id;state().contentResult=result||null;S.opsOpen=null;S.quote=null;render();};
window.v11ContentDownload=function(){const f=curContentFile();if(!f)return;const a=selectedResult(f);download(new Blob([a?a.md:(f.contentMd??f.md??'')],{type:'text/markdown;charset=utf-8'}),(a?a.name:output(f)).split('/').at(-1));};
window.matContentHtml=function(){const files=visible().filter(completed),f=curContentFile();const left='<div class="panel-left"><div class="pl-head">解析文件 · Markdown</div><div class="filelist">'+files.map(x=>'<button class="file-row '+(x===f&&!selectedResult(x)?'sel':'')+'" style="width:100%;text-align:left" data-content-file="'+x.id+'" onclick="v11OpenContent(\''+x.id+'\')">📄 <span class="fn">'+esc(output(x))+'</span><span class="tag gray">'+ST_LABEL[x.status][0]+'</span></button>'+(x.contentResults||[]).map(a=>'<button class="file-row '+(x===f&&selectedResult(x)===a?'sel':'')+'" style="width:calc(100% - 16px);margin-left:16px;text-align:left" data-content-result="'+a.id+'" onclick="v11OpenContent(\''+x.id+'\',\''+a.id+'\')">↳ '+esc(a.name)+'</button>').join('')).join('')+'</div></div>';if(!f)return left+'<div class="doc-area"><div class="doc-empty">暂无解析成功的 Markdown，请先完成文件解析。</div></div>';const a=selectedResult(f),locked=f.status==='parsed',final=f.status==='contentFinal',text=a?a.md:(f.contentMd??f.md??'');const toolbar='<div class="doc-toolbar"><span data-material-title="content">'+esc(a?a.name:output(f))+'</span><div class="viewmode">'+[['preview','预览'],['src','Markdown 源码']].map(([key,label])=>'<button onclick="S.contentViewMode=\''+key+'\';render()">'+label+'</button>').join('')+'</div><button onclick="v11ContentDownload()">⬇ 下载</button>'+(!a&&!locked?(final?'<button disabled>✓ 内容解析已定稿</button><button onclick="contentMenu(this,\''+f.id+'\')">⋯</button>':'<button class="green" onclick="finalContent(\''+f.id+'\')">✓ 内容解析定稿</button>'):'')+'</div>';const notice=locked?'<div class="banner warn">可查看解析稿；需先在文件解析页完成定稿，才能加工。</div>':a?'<div class="banner warn">'+esc(a.mode)+'；此处只读查看，不替主稿定稿。'+(a.sourceContent!==f.md?' 来源解析稿已变化，请重新核对。':'')+'</div>':'<div class="dz-note" style="padding:8px">'+(f.contentMd!=null?'当前显示加工后的内容稿，原始解析稿未覆盖。':'当前显示原始解析 Markdown。')+'</div>';return left+'<div class="doc-area">'+toolbar+notice+'<div class="doc-scroll"><div class="doc-paper">'+(S.contentViewMode==='src'?'<pre class="md-src">'+esc(text)+'</pre>':'<div class="md">'+mdRender(text)+'</div>')+'</div></div></div>'+(!locked&&!a?opsColHtml(f):'');};
const priorOpsCol=window.opsColHtml;window.opsColHtml=function(f){const t=document.createElement('template');t.innerHTML=priorOpsCol(f);if(S.opsOpen&&!['translate','index','mask','term'].includes(S.opsOpen)){const panel=t.content.querySelector('.ops-panel');if(panel)panel.innerHTML='<div class="pl-head">加工结果</div>'+((f.contentResults||[]).map(a=>'<button class="file-row" onclick="v11OpenContent(\''+f.id+'\',\''+a.id+'\')">'+esc(a.name)+'</button>').join('')||'<p class="dz-note">暂无可查看的加工结果；旧版仅有名称的附件不代表已有正文。</p>');}return t.innerHTML;};
const priorFinalContent=window.finalContent;window.finalContent=function(id){const f=visible().find(f=>f.id===id);if(!f||f.status!=='fileFinal'||selectedResult(f)){toast('请先完成文件解析定稿，并在主内容稿上确认','warn');return;}return priorFinalContent(id);};
const priorOp=window.runOp;window.runOp=function(k){const f=curContentFile();if(!f||!['fileFinal','contentFinal'].includes(f.status)||selectedResult(f)){toast('需先完成文件解析定稿，并选择主稿进行加工','warn');return;}if(f.status==='contentFinal'){toast('已定稿，请先解锁再处理','warn');return;}if(k!=='translate')return priorOp(k);if(f.originalBlob){toast('离线原型不支持任意上传文件的真实翻译，未生成译文','warn');return;}const language=document.querySelector('#op-lang')?.value;if(!['中文','英语','法语'].includes(language))return;const samples={'中文':'# 喀麦隆门户网站\n\n本演示项目支持法文和英文，源码应交付客户。','英语':'# Cameroon Government Portal\n\nThe demonstration portal supports French and English. Source code is to be delivered to the client.','法语':'# Portail gouvernemental du Cameroun\n\nLe portail de démonstration prend en charge le français et l’anglais. Le code source doit être livré au client.'};const result={id:uid(),sourceId:f.id,sourceContent:f.md,name:output(f).replace(/\.md$/,'')+'.译文-'+language+'.md',mode:'离线模拟译文样例（非当前文档的逐文翻译）',md:'> 模拟译文：以下仅展示喀麦隆门户场景的译文查看流程，不代表当前文档的完整翻译。\n\n'+samples[language]};(f.contentResults||(f.contentResults=[])).push(result);if(!f.ops.includes('翻译'))f.ops.push('翻译');state().contentResult=result.id;logEvent('stage.material',output(f)+' 创建模拟译文查看样例');render();};
const priorContext=window.ctxDocInfo;window.ctxDocInfo=function(){if(S.route==='stage-material'){const f=S.matTab==='content'?curContentFile():visible().filter(completed).find(f=>f.id===S.selFile)||visible().find(completed);if(f){const a=S.matTab==='content'?selectedResult(f):null;return {id:f.id,name:a?a.name:output(f),md:a?a.md:S.matTab==='content'?(f.contentMd??f.md??''):(f.md||'')};}}return priorContext.apply(this,arguments);};
const priorSend=window.sendChat;window.sendChat=function(){const f=S.route==='stage-material'&&S.matTab==='content'?curContentFile():null;if(f&&(selectedResult(f)||f.status==='parsed')){toast('当前为只读查看，请选择已完成文件解析定稿的主稿再发送加工请求','warn');return;}return priorSend.apply(this,arguments);};
})();
